// Function to process the TSV data
function parseTsvToObjects(tsvData) {
    // 1. Split the data into individual lines
    const lines = tsvData.split('\n').filter(line => line.trim() !== '');

    if (lines.length === 0) {
        return []; // Return empty array if no data lines
    }

    // 2. The first line contains the column headers
    // Splitting by '\t' (tab) to get an array of header names
    const headers = lines[0].split('\t');

    // 3. Process the remaining lines (the data rows)
    const dataObjects = [];
    for (let i = 1; i < lines.length; i++) {
        // Split the data line by '\t' (tab) to get the values
        const values = lines[i].split('\t');
        const item = {};

        // Create an object where keys are headers and values are the corresponding data
        for (let j = 0; j < headers.length; j++) {
            // Trim headers and values for cleaner data
            const key = headers[j].trim();
            const value = values[j] ? values[j].trim() : '';

            // Handle potential excess values/headers mismatch gracefully, though ideally TSV is consistent
            if (key) {
                item[key] = value;
            }
        }
        dataObjects.push(item);
    }

    return dataObjects;
}

// Get the data from the input node. Assumes the data field is in the first item.
const inputItem = $input.first();
const tsvString = inputItem.json.data;

// Parse the TSV string into an array of JSON objects
const resultObjects = parseTsvToObjects(tsvString);

// n8n Code node expects an array of objects, each containing a 'json' property
const outputData = resultObjects.map(item => ({
    json: item
}));

return outputData;

