// Get input data
const allRows = $input.first().json.data;

// Group rows by campaign name
const grouped = {};
allRows.forEach(row => {
  const name = row.campaignName;
  if (!grouped[name]) grouped[name] = [];
  grouped[name].push(row);
});

// Get yesterday's date (YYYY-MM-DD)
const now = new Date();
now.setDate(now.getDate() - 1);
const date = now.toISOString().slice(0, 10);

// Build reports
const results = Object.entries(grouped).map(([campaignName, rows]) => {
  let totalSales = 0, totalSpend = 0, totalClicks = 0, totalImpr = 0;

  rows.forEach(r => {
    totalSales += Number(r.sales7d) || 0;
    totalSpend += Number(r.spend) || 0;
    totalClicks += Number(r.clicks) || 0;
    totalImpr += Number(r.impressions) || 0;
  });

  let out = `📊 Daily Report - ${campaignName}

📅 Report Date - ${date}\n\n`;

  out += `💵 Sales\n\n`;
  out += `- Ordered Product Sales: ${totalSales.toFixed(2)} USD\n\n`;

  out += `📱 Traffic\n\n`;
  out += `- Clicks: ${totalClicks}\n`;
  out += `- Impressions: ${totalImpr}\n`;
  out += `- Spend: ${totalSpend.toFixed(2)} USD\n`;

  return { json: { report: out.trim() } };
});

return results;

